INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,retry_policy,rollback_policy,error_contract) VALUES ('system.credentials.issue','system','Issue one short-lived, operation-scoped owner read API credential using a normal Auth session. The secret is displayed once; declared units are not money. Contract v1.0.0.','system:write',true,'{"type":"object","required":["operations","ttl_seconds","requests_per_minute","declared_unit_budget"],"properties":{"operations":{"type":"array","minItems":1,"maxItems":32,"uniqueItems":true,"items":{"type":"string","pattern":"^[a-z][a-z0-9_.-]{2,100}$"}},"ttl_seconds":{"type":"integer","minimum":60,"maximum":3600},"requests_per_minute":{"type":"integer","minimum":1,"maximum":60},"declared_unit_budget":{"type":"integer","minimum":0,"maximum":1000000}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","credential_id","principal_id","tenant_id","operations","expires_at","requests_per_minute","declared_unit_budget","unit_kind","api_key","display_once","transport"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"credential_id":{"type":"string","format":"uuid"},"principal_id":{"type":"string","format":"uuid"},"tenant_id":{"type":"null"},"operations":{"type":"array","minItems":1,"maxItems":32,"uniqueItems":true,"items":{"type":"string","pattern":"^[a-z][a-z0-9_.-]{2,100}$"}},"expires_at":{"type":"string","format":"date-time"},"requests_per_minute":{"type":"integer","minimum":1,"maximum":60},"declared_unit_budget":{"type":"integer","minimum":0,"maximum":1000000},"unit_kind":{"const":"caller_declared_units_not_money"},"api_key":{"type":"string","pattern":"^sandy_api_[a-f0-9-]{36}\\.[A-Za-z0-9_-]{43}$"},"display_once":{"const":true},"transport":{"type":"object","required":["authorization","key_header"],"properties":{"authorization":{"const":"Bearer <public anon JWT>"},"key_header":{"const":"x-sandy-api-key"}},"additionalProperties":false}},"additionalProperties":false}'::jsonb,'sandy-operation-api',false,false,false,false,'source_ready','ausstyle/web-staging','supabase/functions/sandy-operation-api/policy_operations.ts','["enabled_controller_owner","normal_controller_auth_session","sandy_api_access_audit_schema"]'::jsonb,'{"safe_to_retry":false,"automatic":false,"reason":"Lost issuance returns only a credential identifier for reconciliation/revocation; no secret replay"}'::jsonb,'{"applicable":false,"reason":"Revoke an issued credential with the separately authorized revoke operation"}'::jsonb,'{"version":"1.0.0","api_key_delegable":false,"normal_user_session_required":true,"tenant_execution_supported":false,"external_anchor_established":false,"unknown_mutation_outcome":"reconciliation_required"}'::jsonb) ON CONFLICT(operation) DO NOTHING;
INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,retry_policy,rollback_policy,error_contract) VALUES ('system.credentials.revoke','system','Idempotently revoke an owned scoped Sandy API credential using a normal Auth session. Never accepts an API key or a worker lease as an administrative identity. Contract v1.0.0.','system:write',true,'{"type":"object","required":["credential_id"],"properties":{"credential_id":{"type":"string","format":"uuid"}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","credential_id","revoked","already_revoked"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"credential_id":{"type":"string","format":"uuid"},"revoked":{"const":true},"already_revoked":{"type":"boolean"}},"additionalProperties":false}'::jsonb,'sandy-operation-api',false,false,false,false,'source_ready','ausstyle/web-staging','supabase/functions/sandy-operation-api/policy_operations.ts','["enabled_controller_owner","normal_controller_auth_session","sandy_api_access_audit_schema"]'::jsonb,'{"safe_to_retry":true,"automatic":false,"reason":"Read-only operation or idempotent revocation; no provider dispatch"}'::jsonb,'{"applicable":false,"reason":"No provider compensation is applicable"}'::jsonb,'{"version":"1.0.0","api_key_delegable":false,"normal_user_session_required":true,"tenant_execution_supported":false,"external_anchor_established":false,"unknown_mutation_outcome":"reconciliation_required"}'::jsonb) ON CONFLICT(operation) DO NOTHING;
INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,retry_policy,rollback_policy,error_contract) VALUES ('system.audit.list','system','Read the owner audit hash chain with an exclusive sequence cursor and optional exact operation filter. Returns digests rather than arguments, results, grants or secrets; external retention is still required for independent trust. Contract v1.0.0.','system:read',false,'{"type":"object","required":[],"properties":{"after_sequence":{"type":"integer","minimum":0,"maximum":9007199254740991},"limit":{"type":"integer","minimum":1,"maximum":500},"operation":{"type":"string","pattern":"^[a-z][a-z0-9_.-]{2,100}$"}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","events","limit","next_sequence","possibly_truncated","external_anchor_established"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"events":{"type":"array","maxItems":500,"items":{"type":"object","required":["sequence","id","occurred_at","actor_id","operation","request_id","credential_id","admission_id","phase","outcome","input_sha256","result_sha256","provider_http_status","provider_request_id_sha256","previous_sha256","event_sha256","format"],"properties":{"sequence":{"type":"integer","minimum":0,"maximum":9007199254740991},"id":{"type":"string","format":"uuid"},"occurred_at":{"type":"string","format":"date-time"},"actor_id":{"type":["string","null"],"format":"uuid"},"operation":{"type":["string","null"]},"request_id":{"type":["string","null"],"format":"uuid"},"credential_id":{"type":["string","null"],"format":"uuid"},"admission_id":{"type":["string","null"],"format":"uuid"},"phase":{"type":"string","minLength":1,"maxLength":120},"outcome":{"type":"string","minLength":1,"maxLength":120},"input_sha256":{"type":["string","null"],"pattern":"^[a-f0-9]{64}$"},"result_sha256":{"type":["string","null"],"pattern":"^[a-f0-9]{64}$"},"provider_http_status":{"type":["integer","null"],"minimum":100,"maximum":599},"provider_request_id_sha256":{"type":["string","null"],"pattern":"^[a-f0-9]{64}$"},"previous_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"event_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"format":{"const":"pg_jsonb_v1"}},"additionalProperties":false}},"limit":{"type":"integer","minimum":1,"maximum":500},"next_sequence":{"type":["integer","null"],"minimum":1,"maximum":9007199254740991},"possibly_truncated":{"type":"boolean"},"external_anchor_established":{"const":false}},"additionalProperties":false}'::jsonb,'sandy-operation-api',true,false,true,false,'source_ready','ausstyle/web-staging','supabase/functions/sandy-operation-api/policy_operations.ts','["enabled_controller_owner","normal_controller_auth_session","sandy_api_access_audit_schema"]'::jsonb,'{"safe_to_retry":true,"automatic":false,"reason":"Read-only operation or idempotent revocation; no provider dispatch"}'::jsonb,'{"applicable":false,"reason":"No provider compensation is applicable"}'::jsonb,'{"version":"1.0.0","api_key_delegable":false,"normal_user_session_required":true,"tenant_execution_supported":false,"external_anchor_established":false,"unknown_mutation_outcome":"reconciliation_required"}'::jsonb) ON CONFLICT(operation) DO NOTHING;
INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,retry_policy,rollback_policy,error_contract) VALUES ('system.audit.checkpoint','system','Record a database audit checkpoint for an authenticated owner. Return the digest for separately authorized external retention; no external anchor is claimed or written. Contract v1.0.0.','system:write',true,'{"type":"object","required":[],"properties":{},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","checkpoint","external_anchor_established","limitation"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"checkpoint":{"type":"object","required":["id","sequence","event_sha256","recorded_at","recorded_by"],"properties":{"id":{"type":"string","format":"uuid"},"sequence":{"type":"integer","minimum":0,"maximum":9007199254740991},"event_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"recorded_at":{"type":"string","format":"date-time"},"recorded_by":{"type":"string","format":"uuid"}},"additionalProperties":false},"external_anchor_established":{"const":false},"limitation":{"const":"Database administrators can rewrite both chain and checkpoints; retain checkpoint externally for independent trust"}},"additionalProperties":false}'::jsonb,'sandy-operation-api',false,false,false,false,'source_ready','ausstyle/web-staging','supabase/functions/sandy-operation-api/policy_operations.ts','["enabled_controller_owner","normal_controller_auth_session","sandy_api_access_audit_schema"]'::jsonb,'{"safe_to_retry":false,"automatic":false,"reason":"Checkpoint inserts are not idempotent; do not automatically retry an unknown result"}'::jsonb,'{"applicable":false,"reason":"No provider compensation is applicable"}'::jsonb,'{"version":"1.0.0","api_key_delegable":false,"normal_user_session_required":true,"tenant_execution_supported":false,"external_anchor_established":false,"unknown_mutation_outcome":"reconciliation_required"}'::jsonb) ON CONFLICT(operation) DO NOTHING;
INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,retry_policy,rollback_policy,error_contract) VALUES ('system.audit.verify','system','Verify a bounded audit-chain range against the stored head and optional caller-retained preceding digest. Reports incomplete verification and invalid hashes truthfully; a database checkpoint alone is not independent trust. Contract v1.0.0.','system:read',false,'{"type":"object","required":[],"properties":{"after_sequence":{"type":"integer","minimum":0,"maximum":9007199254740991},"expected_previous_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"limit":{"type":"integer","minimum":1,"maximum":5000}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","valid","checked_events","last_sequence","last_sha256","complete","failed_sequence","reason","caller_supplied_anchor","external_anchor_established"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"valid":{"type":"boolean"},"checked_events":{"type":"integer","minimum":0,"maximum":5000},"last_sequence":{"type":["integer","null"],"minimum":0,"maximum":9007199254740991},"last_sha256":{"type":["string","null"],"pattern":"^[a-f0-9]{64}$"},"complete":{"type":"boolean"},"failed_sequence":{"type":["integer","null"],"minimum":1,"maximum":9007199254740991},"reason":{"enum":[null,"audit_head_mismatch","chain_hash_mismatch"]},"caller_supplied_anchor":{"type":"boolean"},"external_anchor_established":{"const":false}},"additionalProperties":false}'::jsonb,'sandy-operation-api',true,false,true,false,'source_ready','ausstyle/web-staging','supabase/functions/sandy-operation-api/policy_operations.ts','["enabled_controller_owner","normal_controller_auth_session","sandy_api_access_audit_schema"]'::jsonb,'{"safe_to_retry":true,"automatic":false,"reason":"Read-only operation or idempotent revocation; no provider dispatch"}'::jsonb,'{"applicable":false,"reason":"No provider compensation is applicable"}'::jsonb,'{"version":"1.0.0","api_key_delegable":false,"normal_user_session_required":true,"tenant_execution_supported":false,"external_anchor_established":false,"unknown_mutation_outcome":"reconciliation_required"}'::jsonb) ON CONFLICT(operation) DO NOTHING;
